INSERT INTO public.products (name, description, price, image_url, category_slug, stock, is_active, is_popular, allergens, storage_method, shelf_life) VALUES
  ('정성 상견례 세트', '첫 만남의 설레임을 담아 정성스럽게 만든 화과자 세트. 봄 꽃 모양의 네리키리와 함께 격조 있는 선물을 전하세요.', 85000, 'https://picsum.photos/seed/wagashi1/600/600', 'sanggyeonrye', 20, true, true, '찹쌀가루, 팥앙금, 백앙금, 천연색소', '냉장', '제조일로부터 5일'),
  ('매화 상견례 2인 세트', '매화 꽃잎을 형상화한 섬세한 화과자. 두 가문의 첫 만남을 아름답게 장식합니다.', 48000, 'https://picsum.photos/seed/wagashi2/600/600', 'sanggyeonrye', 15, true, false, '백앙금, 한천, 천연색소, 흑임자', '냉장', '제조일로부터 5일'),
  ('격조 상견례 선물함', '고급 오동나무 상자에 담긴 프리미엄 화과자. 격식 있는 자리에 어울리는 품격 있는 선물입니다.', 120000, 'https://picsum.photos/seed/wagashi3/600/600', 'sanggyeonrye', 8, true, true, '찹쌀가루, 팥앙금, 백앙금, 계피, 천연색소', '냉장', '제조일로부터 5일'),
  ('오복 환갑 선물 세트', '오복을 담은 다섯 가지 모양의 화과자. 어르신의 건강과 장수를 기원하는 마음을 담았습니다.', 98000, 'https://picsum.photos/seed/wagashi4/600/600', 'birthday', 12, true, true, '찹쌀가루, 팥앙금, 백앙금, 호박, 흑임자', '냉장', '제조일로부터 5일'),
  ('국화 칠순 화과자', '국화꽃을 형상화한 화과자로 어르신의 칠순을 축하합니다. 전통의 맛과 현대적 감각을 담았습니다.', 65000, 'https://picsum.photos/seed/wagashi5/600/600', 'birthday', 18, true, false, '백앙금, 식용 국화, 한천, 천연색소', '냉장', '제조일로부터 5일'),
  ('수복강녕 8종 세트', '수·복·강·녕을 담은 여덟 가지 화과자 프리미엄 세트. 귀한 어른께 드리기 최적인 고급 선물입니다.', 145000, 'https://picsum.photos/seed/wagashi6/600/600', 'birthday', 6, true, false, '찹쌀가루, 팥앙금, 백앙금, 오미자, 치자, 흑임자', '냉장', '제조일로부터 5일'),
  ('복숭아 돌잔치 세트', '장수를 상징하는 복숭아 모양의 귀여운 화과자. 아이의 첫 생일을 특별하게 만들어 드립니다.', 55000, 'https://picsum.photos/seed/wagashi7/600/600', 'dol', 25, true, true, '찹쌀가루, 백앙금, 딸기분말, 천연색소', '냉장', '제조일로부터 5일'),
  ('곰돌이 돌화과자 6종', '아이들이 좋아하는 귀여운 동물 모양 화과자. 달콤한 맛으로 돌잔치를 더욱 풍성하게 합니다.', 42000, 'https://picsum.photos/seed/wagashi8/600/600', 'dol', 30, true, false, '백앙금, 흑임자앙금, 천연색소', '냉장', '제조일로부터 5일');
